async def close(self) -> None:
        if not hasattr(self, "_close_lock"):
            self._close_lock = asyncio.Lock()
        async with self._close_lock:
            try:
                if self.proc:
                    self.last_check_at = datetime.now()
                    if self.proc.stdin is not None:
                        self.proc.stdin.close()
                    try:
                        os.killpg(os.getpgid(self.proc.pid), signal.SIGKILL)
                    except ProcessLookupError:
                        pass
                    await self.proc.wait()
                    tasks = [task for task in (self._cpu_task, self._mem_task) if task]
                    for task in tasks:
                        task.cancel()
                    if tasks:
                        await asyncio.gather(*tasks, return_exceptions=True)
                    if db.connected:
                        await prisma.repl.update(
                            where={"uuid": str(self.uuid)}, data={"status": ReplStatus.STOPPED}
                        )
            finally:
                benchmark_memory.activity(self, None, "closed")
                benchmark_memory.release(self)


async def close_verbose(repl: Repl) -> None:
    uuid = repl.uuid
    logger.info(f"Closing REPL {uuid.hex[:8]}")
    await repl.close()
    del repl
    logger.info(f"Closed REPL {uuid.hex[:8]}")
